const names = ["writing-semantics","validating-proof"];
for (const name of names) {
  const m = ALL_TOOLS.find(x => x.name === "functions.exec_command");
  text("reading " + name);
  const r = await tools.exec_command({
    cmd: "wc -l /home/agent/.audit-supervisor.gY7Kno/codex-home/skills/" + name + "/SKILL.md && sed -n '1,520p' /home/agent/.audit-supervisor.gY7Kno/codex-home/skills/" + name + "/SKILL.md",
    workdir: "/audit-output",
    yield_time_ms: 10000,
    max_output_tokens: 30000
  });
  text(r.output);
}

const files = [
"/home/agent/.audit-supervisor.gY7Kno/codex-home/skills/shared/proof-extension-soundness.md",
"/home/agent/.audit-supervisor.gY7Kno/codex-home/skills/shared/running-k.md",
"/home/agent/.audit-supervisor.gY7Kno/codex-home/skills/shared/k-syntax.md",
"/home/agent/.audit-supervisor.gY7Kno/codex-home/skills/shared/k-claims.md"
];
for (const f of files) {
  text("FILE " + f);
  const r = await tools.exec_command({cmd:"wc -l '"+f+"' && sed -n '1,640p' '"+f+"'",workdir:"/audit-output",yield_time_ms:10000,max_output_tokens:50000});
  text(r.output);
}

const cmds = [
  {
    log:"stage1_provenance_comparison.log",
    lines:400,
    cmd:"set -uo pipefail; for f in prompt.py py2mpy.py; do echo \"COMPARE $f\"; if cmp -s \"/candidate/$f\" \"/reference/$f\"; then echo \"BYTE_IDENTICAL yes\"; else st=$?; echo \"BYTE_IDENTICAL no cmp_status=$st\"; cmp -l \"/candidate/$f\" \"/reference/$f\" | sed -n \"1,40p\"; fi; sha256sum \"/candidate/$f\" \"/reference/$f\"; done; echo \"REQUIRED ARTIFACT TYPES\"; for f in run-input.json metrics.json codex-last.txt codex-output.log prompt.py py2mpy.py solution.py solution.mpy semantic.k verification.k spec.k prove.sh; do if test -L \"/candidate/$f\"; then echo \"SYMLINK $f -> $(readlink \"/candidate/$f\")\"; elif test -f \"/candidate/$f\"; then stat -c \"REGULAR %a %s %n\" \"/candidate/$f\"; elif test -e \"/candidate/$f\"; then stat -c \"MISTYPED %F %n\" \"/candidate/$f\"; else echo \"MISSING $f\"; fi; done",
  },
  {
    log:"stage1_untrusted_metadata.log",
    lines:650,
    cmd:"set -uo pipefail; for f in run-input.json metrics.json codex-last.txt codex-output.log; do echo \"===== $f =====\"; sed -n \"1,500p\" \"/candidate/$f\"; done; echo \"===== structured trace (bounded) =====\"; trace=$(find /candidate/codex-trace -type f -name \"*.jsonl\" -print -quit); if test -n \"$trace\"; then echo \"TRACE $trace\"; sed -n \"1,200p\" \"$trace\"; else echo \"NO STRUCTURED TRACE\"; fi",
  },
  {
    log:"stage1_source_artifacts.log",
    lines:1000,
    cmd:"set -uo pipefail; for f in prompt.py canonical.py py2mpy.py; do echo \"===== reference/$f =====\"; nl -ba \"/reference/$f\"; done; for f in solution.py solution.mpy semantic.k verification.k spec.k prove.sh; do echo \"===== candidate/$f =====\"; nl -ba \"/candidate/$f\"; done",
  }
];
for (const c of cmds) {
  const r = await tools.exec_command({
    cmd:"/audit-output/evidence/run_logged.sh '"+c.log+"' '"+c.lines+"' bash -lc '"+c.cmd.replaceAll("'","'\"'\"'")+"'",
    workdir:"/audit-output",yield_time_ms:10000,max_output_tokens:30000
  });
  text(c.log + "\n" + r.output);
}

